package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import com.aliothmoon.maafw.rewards.RewardRegionLocator;
/** Report-only aggregation; these objects cannot authorize an action. */
public class VisibleKnownSetReportTest {
 static ReadOnlyTwoStageRun.Observation complete(){return ReadOnlyTwoStageRun.Capture.moreCurrentCards(new Object(),"readonly-complete",1440,2560,0,1000,()->false).prepare(SelectedPendingBusinessTest.afterPixels(),1440,2560,SelectedPendingBusinessTest.afterRows(),()->false);}
 static RewardRegionLocator.CurrentReadBatch with(RewardRegionLocator.CurrentReadBatch b,boolean truncated,int titles,int fragments,List<RewardRegionLocator.CurrentReadCard> cards){return new RewardRegionLocator.CurrentReadBatch(b.status(),b.firstGate(),b.geometryStatus(),b.headerCount(),b.headerFraction(),b.nativeCards(),cards,truncated,titles,fragments);}
 @Test public void realReadonlyTwoOwnTicksAreOnlyFiniteSetFact(){var o=complete();var b=o.currentCards();assertTrue(CaptureSessionRuntime.visibleKnownSetComplete(b,true));assertEquals(2,b.cards().stream().filter(i->i.status()==RewardRegionLocator.CurrentReadStatus.COMPLETE&&i.identity()==RewardRegionLocator.CurrentReadIdentity.UNNAMED).count());String s=CaptureSessionRuntime.qualifiedCurrentReadSummary(o,true,true);assertTrue(s.contains("visibleKnownSetComplete=true"));assertTrue(s.contains("completeFamily=false businessEligible=false"));assertTrue(s.contains("completionCause=UNPROVEN"));assertFalse(o.frame.selectedProofReady());}
 @Test public void unknownOrUnhealthyDoesNotPublishSetCompletion(){var o=complete();assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(null,true));assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(o.currentCards(),false));String s=CaptureSessionRuntime.qualifiedCurrentReadSummary(o,false,true);assertTrue(s.contains("UNQUALIFIED"));assertFalse(s.contains("visibleKnownSetComplete=true"));}
 @Test public void pendingHoldOrMissingTickDoesNotCount(){var o=IndependentCurrentCardTest.observe(IndependentCurrentCardTest.pixels(true),IndependentCurrentCardTest.rows());assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(o.currentCards(),true));var rows=SelectedPendingBusinessTest.afterRows();IndependentCurrentCardTest.replace(rows,712,"10",.99);o=IndependentCurrentCardTest.observe(SelectedPendingBusinessTest.afterPixels(),rows);assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(o.currentCards(),true));}
 @Test public void truncationOrGlobalKnownWarningsBlockOnlyAggregate(){var b=complete().currentCards();assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(with(b,true,0,0,b.cards()),true));assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(with(b,false,1,0,b.cards()),true));assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(with(b,false,0,1,b.cards()),true));assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(with(b,false,-1,0,b.cards()),true));}
 @Test public void ExactlyTwoIsNotOneOrThree(){var b=complete().currentCards();var cards=new ArrayList<>(b.cards());var complete=cards.stream().filter(c->c.status()==RewardRegionLocator.CurrentReadStatus.COMPLETE).findFirst().orElseThrow();cards.remove(complete);assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(with(b,false,0,0,cards),true));cards=new ArrayList<>(b.cards());cards.add(complete);assertFalse(CaptureSessionRuntime.visibleKnownSetComplete(with(b,false,0,0,cards),true));}
}
